/* Connected design prototype. No requests, accounts, payments or invitations leave this browser. */
const KEY='digitatalent-pulse-product-preview-v1';
const DOMAINS=['Data & information','Communication','Digital content','Safety','Problem solving','AI literacy'];
const SHORT=['Data','Communication','Content','Safety','Problem solving','AI'];
const TIERS=['Basic','Intermediate','Advanced'];
const LEVEL=['Pending','Basic','Intermediate','Advanced'];
const ART='../assets/learning-journey-abstract.png';
const ARCH='../assets/competency-architecture.png';
const $=selector=>document.querySelector(selector);
const esc=value=>String(value??'').replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]));
const id=()=>Math.random().toString(36).slice(2,10);
const courseId=(domain,tier)=>`${domain}-${tier}`;
const parseCourse=value=>{const [domain,tier]=String(value||'0-1').split('-').map(Number);return {domain:Number.isInteger(domain)&&domain>=0&&domain<6?domain:0,tier:Number.isInteger(tier)&&tier>=1&&tier<=3?tier:1}};
const courseName=value=>{const c=parseCourse(value);return `${DOMAINS[c.domain]} · ${TIERS[c.tier-1]}`};
const fresh=()=>({org:'',ownerEmail:'',verified:false,role:'public',demo:false,published:false,business:[3,3,2,2,2,1],departments:[{name:'Accounting',ceiling:[2,2,2,2,2,1],manager:'',positions:[{name:'Accountant',target:[2,2,1,2,2,1]}]}],employees:[],enrollments:[],purchases:{},proposals:[],cooldownHours:48,deadlineDays:7,timeOffsetHours:0,events:[]});
function sample(){const s=fresh();s.org='Northstar Studio';s.ownerEmail='owner@northstar.example';s.verified=true;s.published=true;s.role='owner';s.demo=true;s.departments[0].manager='Nora Park';s.departments.push({name:'Marketing',ceiling:[2,3,2,2,2,1],manager:'Jordan Lee',positions:[{name:'Marketing Specialist',target:[1,2,2,2,1,1]}]});s.employees=[{id:'mia',name:'Mia Nguyen',email:'mia@northstar.example',dept:'Accounting',position:'Accountant',current:[1,1,0,2,1,0],assessed:true},{id:'ben',name:'Ben Dao',email:'ben@northstar.example',dept:'Accounting',position:'Accountant',current:[1,1,1,1,1,0],assessed:true},{id:'ava',name:'Ava Le',email:'ava@northstar.example',dept:'Marketing',position:'Marketing Specialist',current:[1,2,1,2,1,0],assessed:true}];s.enrollments=[{employeeId:'mia',courseId:'0-1',lessons:[true,false,false],finalCheck:false,attempts:[],status:'learning',releaseAt:null,deadlineAt:null,assignedAt:Date.now()}];s.events=[{at:Date.now()-86400000*6,title:'Capability blueprint published',detail:'Business, department and position ceilings were confirmed.'},{at:Date.now()-86400000*5,title:'Employees routed to positions',detail:'Accounting and Marketing Employees received their position targets.'},{at:Date.now()-86400000*4,title:'Baseline assessment completed',detail:'Mia’s current capability was measured across the six domains.'},{at:Date.now()-86400000*3,title:'Basic course started',detail:'Data & information · Basic opened for Mia.'}];return s}
let state=(()=>{try{const saved=JSON.parse(localStorage.getItem(KEY));return saved&&Array.isArray(saved.departments)?saved:fresh()}catch{return fresh()}})();
let importRows=[];
const save=()=>localStorage.setItem(KEY,JSON.stringify(state));
const now=()=>Date.now()+(state.timeOffsetHours||0)*3600000;
const date=stamp=>new Intl.DateTimeFormat('en',{day:'numeric',month:'short',year:'numeric'}).format(new Date(stamp));
const event=(title,detail)=>state.events.unshift({at:now(),title,detail});
const toast=(message)=>{const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),3500)};
const route=()=>decodeURIComponent(location.hash.replace(/^#\/?/,'').split('?')[0]||'welcome');
function go(path){location.hash=`#/${path.replace(/^\//,'')}`;window.scrollTo({top:0,behavior:'instant'});render()}
const link=(path,label,kind='btn-outline',extra='')=>`<a class="btn ${kind} ${extra}" href="#/${path}">${label}</a>`;
const icon=(text)=>`<span aria-hidden="true">${text}</span>`;
function employee(){return state.employees[0]||null}
function department(name){return state.departments.find(d=>d.name===name)}
function position(person){return department(person?.dept)?.positions.find(p=>p.name===person.position)}
function enrollment(course,person=employee()){return state.enrollments.find(e=>e.courseId===course&&e.employeeId===person?.id)}
function approved(course,person=employee()){return enrollment(course,person)?.status==='approved'}
function courseAccess(course,person=employee()){const c=parseCourse(course);return c.tier===1||Boolean(enrollment(course,person))}
function courseEligible(course,person=employee()){const c=parseCourse(course);return c.tier===1||approved(courseId(c.domain,c.tier-1),person)}
function stepCount(){return state.enrollments.filter(e=>e.status==='approved').length}
function gapCount(person){const target=position(person)?.target||[];return target.filter((t,i)=>t>0&&person?.current?.[i]>0&&person.current[i]<t).length}
function recommended(person){const target=position(person)?.target||[];for(let i=0;i<target.length;i++){if(!(target[i]>0&&person?.current?.[i]>0&&person.current[i]<target[i]))continue;for(let tier=1;tier<=target[i];tier++){const next=courseId(i,tier);if(!approved(next,person))return next}}return courseId(0,1)}
function currentDept(){return state.departments[0]}
function rolePath(role){return {owner:'owner',manager:'manager',employee:'employee'}[role]||'welcome'}
const page=(eyebrow,title,description,actions='')=>`<div class="page-head"><div><span class="eyebrow">${eyebrow}</span><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="page-actions">${actions}</div>`:''}</div>`;
const box=(content,className='')=>`<section class="surface pad ${className}">${content}</section>`;
const notice=(content,type='')=>`<div class="notice ${type}">${content}</div>`;
const badge=(text,type='')=>`<span class="pill ${type}">${text}</span>`;
function header(path){const publicPage=!state.verified||['welcome','register','login','verify'].includes(path),learning=state.role==='employee'&&!publicPage;return `<header class="app-header"><a class="brand" href="#/welcome" aria-label="DigiTalent Pulse home"><img src="../assets/pulse-mark.svg" alt=""><span>DigiTalent <em>Pulse</em></span></a>${publicPage?`<nav class="top-links" aria-label="Main"><a href="#/welcome#how">How it works</a><a href="#/catalog">Courses</a><a href="#/welcome#approach">Approach</a></nav>`:learning?`<nav class="employee-nav" aria-label="Employee"><a class="${path==='employee'?'active':''}" href="#/employee">Today</a><a class="${path==='path'?'active':''}" href="#/path">Path</a><a class="${path==='assignment'?'active':''}" href="#/assignment">Practice</a></nav>`:`<nav class="top-links" aria-label="Workspace"><a href="#/owner">Overview</a><a href="#/gap">Capability</a><a href="#/catalog">Courses</a><a href="#/report">Reports</a></nav>`}<div class="header-actions">${publicPage?`${link('login','Sign in','btn-outline btn-small')}${link('register','Start free','btn-primary btn-small')}`:`<span class="prototype-chip">Interactive preview</span><label class="sr-only" for="role-switch">Preview role</label><select id="role-switch" aria-label="Preview role"><option value="owner" ${state.role==='owner'?'selected':''}>Owner</option><option value="manager" ${state.role==='manager'?'selected':''}>Manager</option><option value="employee" ${state.role==='employee'?'selected':''}>Employee</option></select>`}</div></header>`}
function side(path){const owner=[['Overview','owner','◫'],['Blueprint','setup','◇'],['People','people','♙'],['Capability gap','gap','▥'],['Courses','catalog','▤'],['Cycle reports','report','▣']];const manager=[['Overview','manager','◫'],['Team capability','gap','▥'],['Final assignments','review','◎'],['Cycle reports','report','▣']];const items=state.role==='manager'?manager:owner;return `<aside class="sidebar"><div class="side-group"><span class="side-label">${state.role==='manager'?'Team manager':'Enterprise owner'}</span>${items.map(([label,target,glyph])=>`<a class="side-link ${path===target?'active':''}" href="#/${target}"><b>${glyph}</b>${label}</a>`).join('')}</div><div class="side-foot"><b>${esc(state.org)}</b>${state.role==='manager'?`Manager · ${esc(currentDept()?.name||'Accounting')}`:'Free trial · no expiry'}<br>${state.employees.length}/10 Employee seats</div></aside>`}
function shell(path,content){const publicPage=!state.verified||['welcome','register','login','verify'].includes(path);if(publicPage)return `${header(path)}${content}`;if(state.role==='employee')return `${header(path)}<div class="employee-shell role-employee"><main class="employee-main">${content}</main></div>`;return `${header(path)}<div class="app-shell role-${state.role}">${side(path)}<main class="main-area">${content}<div class="utility-footer">DigiTalent Pulse · Sample data and browser-local actions only</div></main></div>`}
function landing(){return `<main><section class="hero"><div class="wrap hero-inner"><div class="hero-copy"><span class="eyebrow">Capability, learning and evidence in one place</span><h1>Make learning <em>mean something</em> at work.</h1><p>Set the skills your business needs. See each person's measured starting point. Guide their learning, review real work, and understand the outcome.</p><div class="hero-actions">${link('register','Start your free business trial →','btn-primary') }<button class="btn btn-outline" data-action="sample">Explore sample business</button></div><div class="hero-note"><strong>Free, with no time limit</strong><span>10 Employee seats · all Basic courses included</span></div></div><div class="hero-art"><img src="${ART}" alt="Abstract glass platforms connected by a blue learning path, with coral and lime accents"><div class="floating-note"><b>One path. Visible progress.</b><span>From a measured baseline to a Manager-reviewed outcome.</span><i></i></div></div></div></section><div class="stats-strip"><div><strong>01 · Define</strong><span>Your business, department and position targets</span></div><div><strong>02 · Develop</strong><span>Learning chosen for each measured gap</span></div><div><strong>03 · Demonstrate</strong><span>Course evidence and a complete cycle report</span></div></div><section class="section" id="how"><div class="wrap"><span class="eyebrow">A connected journey</span><h2 class="section-title">A clear route from intent to impact.</h2><p class="section-lead">The experience follows one business through setup, learning, review and the report at the end of each course cycle.</p><div class="story-grid"><article class="story-card"><span class="number">01 / DEFINE THE NEED</span><h3>Set a target that belongs to your business.</h3><p>Start from the Digital AI framework. Set a business ceiling, shape each department, then define the exact target for every position.</p></article><article class="story-card"><span class="number">02 / MAKE IT PERSONAL</span><h3>See where each Employee begins.</h3><p>Route people by department and position. Compare their baseline assessment with the target before building their learning path.</p></article><article class="story-card"><span class="number">03 / CLOSE THE LOOP</span><h3>Review evidence. Read the whole story.</h3><p>Managers grade the final assignment in every course with AI suggestions. Owners see a course-cycle report once work is approved.</p></article></div></div></section><section class="section" style="padding-top:10px" id="approach"><div class="wrap split-showcase"><div class="showcase-visual"><img src="${ARCH}" alt="Abstract connected shapes representing a layered capability framework"></div><div><span class="eyebrow">Built around your operating model</span><h2 class="section-title">One framework. A path for each position.</h2><p>Each target stays within the layer above it. A Manager sees their department; each Employee sees their own role. A pending assessment is shown as pending, never as a measured skill gap.</p><div class="showcase-list"><div><b>✓</b>Position target ≤ department ≤ business ≤ Digital AI</div><div><b>✓</b>Basic lessons fully open in the unlimited free trial</div><div><b>✓</b>Advanced access purchased and assigned by course</div></div>${link('register','Create your workspace →','btn-primary')}</div></div></section><section class="section"><div class="wrap"><span class="eyebrow">Designed for the whole team</span><h2 class="section-title">Everyone sees what matters to them.</h2><div class="feature-grid"><article class="feature-card"><i>◇</i><h3>Owner</h3><p>Design ceilings, invite the team, assign course seats and read the full cycle report.</p></article><article class="feature-card"><i>◎</i><h3>Manager</h3><p>Compare team gaps, coach learners and make the final course decision with evidence in view.</p></article><article class="feature-card"><i>↗</i><h3>Employee</h3><p>See a personal gap, follow a focused learning path and submit the final assignment.</p></article></div></div></section><div class="wrap"><div class="landing-end"><div><span class="eyebrow" style="color:#c6ec78">A useful first step</span><h2>Give your team a direction they can see.</h2><p>Start with Basic courses and up to ten Employees. Grow course by course when you need to.</p></div>${link('register','Start free →','btn-primary')}</div><footer class="landing-footer"><span>DigiTalent Pulse · Interactive product design preview</span><span>Illustrative data · no live accounts or payments</span></footer></div></main>`}
function authPage(mode){const register=mode==='register',verify=mode==='verify';return `<div class="auth-layout"><aside class="auth-aside"><span class="eyebrow">DigiTalent Pulse</span><h1>${register?'A clearer way to grow capability.':verify?'Your workspace is one step away.':'Pick up the path where your team left off.'}</h1><p>${register?'Build the framework your business actually needs, then give each person a position-specific path.':'Every measured gap, learning step and Manager decision stays connected.'}</p><img src="${ARCH}" alt="Abstract blue capability architecture"></aside><main class="auth-main"><div class="auth-card"><span class="eyebrow">${verify?'Email verification':register?'Free business trial':'Welcome back'}</span><h2>${verify?'Verify your email':register?'Create your workspace':'Sign in'}</h2><p>${verify?`A verification link would be sent to <strong>${esc(state.ownerEmail||'your email')}</strong>. Continue below to simulate confirmation in this preview.`:register?'No approval queue, no trial deadline. Start with 10 Employee seats and every Basic course.':'Use any email to explore the sample workspace by role. This preview does not authenticate.'}</p>${verify?`<button class="btn btn-primary" data-action="verify">Confirm email in preview →</button><p class="auth-foot">No email is sent from this prototype.</p>`:register?`<form data-form="register"><label class="field">Business name<input name="org" required maxlength="80" placeholder="e.g. Northstar Studio"></label><label class="field">Work email<input name="email" type="email" required placeholder="you@business.com"></label><label class="field">Password<input name="password" type="password" required minlength="8" placeholder="At least 8 characters"><span class="field-hint">Preview only. The password is not stored.</span></label><button class="btn btn-primary" type="submit">Create free workspace →</button></form><p class="auth-foot">Already have a workspace? <a href="#/login">Sign in</a></p>`:`<form data-form="login"><label class="field">Email<input name="email" type="email" required placeholder="name@business.com"></label><label class="field">Preview role<select name="role"><option value="owner">Enterprise Owner</option><option value="manager">Manager</option><option value="employee">Employee</option></select></label><button class="btn btn-primary" type="submit">Enter preview →</button></form><p class="auth-foot">New business? <a href="#/register">Start a free trial</a></p><div class="sample-tip"><b>Preview sign-in</b>Enter any email. A sample organization opens with the role you choose. No password or account is required.</div>`}</div></main></div>`}
let selectedDept=0,selectedPosition=0,selectedEmployeeId='';
function activePerson(){if(state.role==='manager'){const people=state.employees.filter(p=>p.dept===currentDept()?.name);return people.find(p=>p.id===selectedEmployeeId)||people[0]||null}return state.employees.find(p=>p.id===selectedEmployeeId)||employee()}
function flowTrack(current){return `<div class="process-track">${[['Setup','setup'],['People','people'],['Baseline','assessment'],['Gap & path','gap'],['Learn & review','course/0-1'],['Report','report']].map(([label,path],i)=>`<a href="#/${path}" class="${current===path.split('/')[0]?'current':''}"><b>0${i+1}</b><span>${label}</span></a>`).join('')}</div>`}
function ownerHome(){const waiting=state.enrollments.filter(e=>e.status==='pending').length;const complete=stepCount();const first=state.employees[0];return `${page('Enterprise owner · free trial',`Good morning, ${esc(state.org)}.`,`One connected view of capability, learning and course outcomes.`,link('report','View cycle report','btn-outline'))}<div class="stack">${box(`<span class="mini-label">Your next meaningful step</span><h2>${!state.published?'Publish your capability blueprint.':!state.employees.length?'Invite the team into the right positions.':complete?'Your first course cycle has an outcome.':'Turn a measured gap into a learning path.'}</h2><p>${!state.published?'Set business, department and position levels in order before adding people.':!state.employees.length?'Add a Manager, then invite Employees by department and position.':complete?'See the baseline, learning journey, Manager decision and the next recommendation in one report.':`See ${esc(first?.name||'an Employee')}'s tested level beside their position target, then open the recommended course.`}</p><div class="button-row">${link(!state.published?'setup':!state.employees.length?'people':complete?'report':'gap',!state.published?'Finish blueprint →':!state.employees.length?'Invite people →':complete?'Open report →':'See capability gap →','btn-primary')}${link('catalog','Explore courses','btn-outline')}</div>`,'flow-banner')}<div class="grid-4"><div class="surface kpi"><span>Employee seats used</span><strong>${state.employees.length}<small>/10</small></strong><small>Across all departments</small></div><div class="surface kpi"><span>Departments</span><strong>${state.departments.length}</strong><small>With separate ceilings</small></div><div class="surface kpi"><span>Manager reviews due</span><strong>${waiting}</strong><small>Final course assignments</small></div><div class="surface kpi"><span>Approved course cycles</span><strong>${complete}</strong><small>Included in reporting</small></div></div>${flowTrack('owner')}<div class="grid-2">${box(`<span class="mini-label">Capability architecture</span><h2 class="panel-title" style="margin-top:11px">From framework to position.</h2><p class="panel-desc">Your published targets define what each Employee needs to reach.</p><div class="grid-2">${['Digital AI','Business','Department','Position'].map((label,i)=>`<div class="cap-card"><strong>${label}</strong><small>${i===0?'Platform standard':i===1?esc(state.org):i===2?esc(currentDept()?.name):esc(currentDept()?.positions[0]?.name)}</small><div class="bar"><i style="width:${[100,85,65,48][i]}%"></i></div></div>`).join('')}</div><div class="button-row" style="margin-top:20px">${link('setup','Edit blueprint','btn-outline btn-small')}${link('gap','See measured gap','btn-ghost btn-small')}</div>`)}${box(`<span class="mini-label">Training cycle</span><h2 class="panel-title" style="margin-top:11px">Know what happened after learning.</h2><p class="panel-desc">The cycle report opens after the Manager approves a final course assignment.</p><div class="timeline">${state.events.slice(0,3).map(item=>`<div><i></i><time>${date(item.at)}</time><span><strong>${esc(item.title)}</strong><p>${esc(item.detail)}</p></span></div>`).join('')||`<p class="small">Your setup and learning milestones will appear here.</p>`}</div>${link('report','Open cycle report','btn-outline btn-small')}`)}</div>${state.proposals.filter(p=>p.status==='pending').length?box(`<h2 class="panel-title">Manager proposals</h2><p class="panel-desc">Review a department ceiling change before publishing it.</p>${state.proposals.filter(p=>p.status==='pending').map(p=>`<div class="member-row"><span class="avatar">◇</span><div><strong>${esc(p.department)} · ${esc(DOMAINS[p.domain])}</strong><small>Proposed ceiling: ${LEVEL[p.level]}</small></div><button class="btn btn-outline btn-small" data-action="accept-proposal" data-id="${p.id}">Accept into draft</button><button class="btn btn-ghost btn-small" data-action="reject-proposal" data-id="${p.id}">Decline</button></div>`).join('')}`):''}</div>`}
const digital=[3,3,3,3,3,3];
const levelOptions=(value,max=3)=>Array.from({length:4},(_,i)=>`<option value="${i}" ${value===i?'selected':''} ${i>max?'disabled':''}>${LEVEL[i]}</option>`).join('');
function setupPage(){const dept=state.departments[selectedDept]||state.departments[0];const pos=dept.positions[selectedPosition]||dept.positions[0];return `${page('01 / Build your business standard','A blueprint that makes sense for every role.','Digital AI defines the outer ceiling. Your business chooses its own levels, then each department and position inherits a smaller or equal target.',state.published?badge('Published','green'):badge('Draft','coral'))}<div class="stack">${notice(`<strong>Required order:</strong> position target ≤ department ceiling ≤ business ceiling ≤ Digital AI. Publish before inviting Employees.`)}<div class="grid-2">${box(`<span class="mini-label">Business and department</span><h2 class="panel-title" style="margin-top:10px">Choose the team to edit.</h2><label class="field">Department<select id="setup-dept">${state.departments.map((d,i)=>`<option value="${i}" ${selectedDept===i?'selected':''}>${esc(d.name)}</option>`).join('')}</select></label><label class="field">Position<select id="setup-position">${dept.positions.map((p,i)=>`<option value="${i}" ${selectedPosition===i?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><div class="grid-2"><form data-form="add-department"><label class="field">New department<input name="name" required maxlength="50" placeholder="e.g. Operations"></label><button class="btn btn-outline btn-small" type="submit">Add department</button></form><form data-form="add-position"><label class="field">New position in ${esc(dept.name)}<input name="name" required maxlength="50" placeholder="e.g. Finance Lead"></label><button class="btn btn-outline btn-small" type="submit">Add position</button></form></div>`)}${box(`<span class="mini-label">Position-specific path</span><h2 class="panel-title" style="margin-top:10px">${esc(dept.name)} / ${esc(pos.name)}</h2><p class="panel-desc">Every Employee is routed through a department first, then this exact position. The Manager reviews assignments only for their department.</p><div class="cap-card"><strong>Published target chain</strong><small>${esc(pos.name)} ≤ ${esc(dept.name)} ≤ ${esc(state.org)} ≤ Digital AI</small><div class="bar"><i style="width:63%"></i></div></div><div class="divider"></div><label class="field">Wait after first unsuccessful submission (hours)<input id="cooldown" type="number" min="1" max="720" value="${state.cooldownHours}"></label><label class="field">Deadline after second submission opens (days)<input id="deadline" type="number" min="1" max="90" value="${state.deadlineDays}"></label>`)} </div>${box(`<div class="section-subhead" style="margin-top:0"><div><h2>Set levels by domain.</h2><p>The editor prevents a child level from exceeding its parent and a parent from falling below a child.</p></div></div><div class="domain-row header"><span>Digital AI standard</span><span>Business</span><span>Department</span><span>Position</span></div>${DOMAINS.map((name,i)=>`<div class="domain-row"><div><b>${name}</b><small class="dim" style="display:block">Digital AI: ${LEVEL[digital[i]]}</small></div><select aria-label="${name} business level" data-cap="business" data-domain="${i}">${levelOptions(state.business[i],digital[i])}</select><select aria-label="${name} department ceiling" data-cap="department" data-domain="${i}">${levelOptions(dept.ceiling[i],state.business[i])}</select><select aria-label="${name} position target" data-cap="position" data-domain="${i}">${levelOptions(pos.target[i],dept.ceiling[i])}</select></div>`).join('')}<div class="button-row" style="margin-top:22px"><button class="btn btn-primary" data-action="publish">Publish blueprint →</button>${link('people','Continue to people','btn-outline')}</div>`)}${state.proposals.filter(p=>p.status==='pending').length?notice(`${state.proposals.filter(p=>p.status==='pending').length} Manager proposal(s) need an Owner decision. See Overview.`):''}</div>`}
function peoplePage(){const dept=state.departments[0];return `${page('02 / People and routing','Put the right person on the right path.','Create the department Manager, then invite Employees. Department sets the team scope; position sets the exact learning target.',badge(`${state.employees.length}/10 Employee seats`))}<div class="stack">${!state.published?notice('Publish the capability blueprint before sending Employee invitations.','warning'):notice('The free trial has no time limit. Ten active or pending Employee seats cover all departments; Manager accounts do not use these seats.','success')}<div class="grid-2">${box(`<span class="mini-label">Department Manager</span><h2 class="panel-title" style="margin-top:10px">Assign a Manager first.</h2><p class="panel-desc">A Manager sees only people and final assignments in their department.</p><form data-form="manager"><label class="field">Department<select name="department">${state.departments.map(d=>`<option value="${esc(d.name)}">${esc(d.name)}</option>`).join('')}</select></label><label class="field">Manager name<input name="name" required placeholder="e.g. Nora Park" value="${esc(dept.manager)}"></label><button class="btn btn-outline" type="submit">Save Manager</button></form>`)}${box(`<span class="mini-label">Individual Employee invitation</span><h2 class="panel-title" style="margin-top:10px">Route before you invite.</h2><form data-form="invite"><div class="inline-fields"><label class="field">Full name<input name="name" required placeholder="e.g. Mia Nguyen"></label><label class="field">Work email<input type="email" name="email" required placeholder="mia@business.com"></label></div><div class="inline-fields"><label class="field">Department<select id="invite-dept" name="department">${state.departments.map(d=>`<option value="${esc(d.name)}">${esc(d.name)}</option>`).join('')}</select></label><label class="field">Position<select id="invite-position" name="position">${dept.positions.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join('')}</select></label></div><button class="btn btn-primary" type="submit" ${!state.published?'disabled':''}>Add sample Employee →</button></form>`)} </div>${box(`<div class="section-subhead" style="margin-top:0"><div><h2>Import several Employees.</h2><p>CSV columns: email, full_name, department, position. Preview checks before adding rows.</p></div><a class="btn btn-outline btn-small" href="../assets/member-import-template.csv" download>Download template</a></div><label class="field">Choose a CSV file<input id="csv-file" type="file" accept=".csv,text/csv"></label><div id="csv-preview">${importRows.length?csvPreview():`<p class="small">A checked preview will appear here. No real invitations are sent.</p>`}</div>`)}${box(`<div class="section-subhead" style="margin-top:0"><div><h2>Employees by department and position.</h2><p>Invitees see only their assigned position path.</p></div></div>${state.employees.length?state.employees.map(p=>`<div class="member-row"><span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).join(''))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.dept)} · ${esc(p.position)} · ${p.assessed?'Baseline measured':'Assessment pending'}</small></div>${badge(p.assessed?'Measured':'Pending',p.assessed?'green':'gray')}</div>`).join(''):`<div class="empty-state"><div class="icon">♙</div><h2>No Employees yet</h2><p>Invite an Employee after publishing your blueprint. Their department and position will define the target they see.</p></div>`}<div class="button-row" style="margin-top:18px">${link('gap','View capability comparison →','btn-outline')}</div>`)}</div>`}
function csvPreview(){return `<div class="table-scroll"><table class="data-table"><thead><tr><th>Email</th><th>Name</th><th>Department</th><th>Position</th><th>Check</th></tr></thead><tbody>${importRows.map(r=>`<tr><td>${esc(r.email)}</td><td>${esc(r.name)}</td><td>${esc(r.dept)}</td><td>${esc(r.position)}</td><td>${badge(r.error||'Ready',r.error?'coral':'green')}</td></tr>`).join('')}</tbody></table></div><div class="button-row" style="margin-top:16px"><button class="btn btn-primary btn-small" data-action="commit-import" ${!state.published?'disabled':''}>Add valid sample rows</button><span class="small muted">${importRows.filter(r=>!r.error).length} valid · ${10-state.employees.length} seats available</span></div>`}
function gapPanel(person){const target=position(person)?.target||Array(6).fill(0);return `${!person?.assessed?notice('This Employee has not completed the baseline assessment. An unconfirmed level is pending, not a measured gap.','warning'):notice(`Measured baseline for ${esc(person.name)} compared with the ${esc(person.position)} position target.`)}<div class="comparison-legend"><span><b></b>Measured current</span><span><b class="blue"></b>Position target</span></div>${DOMAINS.map((name,i)=>`<div class="gap-row"><div><strong>${name}</strong><small>${person?.current?.[i]>0&&person.assessed&&target[i]>person.current[i]?`Gap of ${target[i]-person.current[i]} level(s)`:person?.current?.[i]>0?'At target or above':'Not confirmed'}</small></div><span class="value">${person?.current?.[i]>0&&person.assessed?`L${person.current[i]}`:'Pending'}</span><div class="gap-bars"><div class="bar coral"><i style="width:${person?.current?.[i]>0&&person.assessed?person.current[i]/3*100:0}%"></i></div><div class="bar"><i style="width:${target[i]/3*100}%"></i></div></div><span class="value target">${target[i]?`L${target[i]}`:'—'}</span></div>`).join('')}`}
function gapPage(){const people=state.role==='manager'?state.employees.filter(p=>p.dept===currentDept()?.name):state.employees;const person=activePerson();const target=position(person)?.target||[];return `${page(state.role==='manager'?'Team capability · department scope':'03 / Baseline and gap','See the starting point beside the goal.','Measured levels and position targets stay side by side, so the next course has a reason.',person?badge(`${gapCount(person)} confirmed gaps`):'')}<div class="stack">${!person?box(`<div class="empty-state"><div class="icon">▥</div><h2>No Employee to compare yet.</h2><p>Publish the blueprint and add an Employee. Their baseline assessment will make this comparison meaningful.</p>${link('people','Add an Employee →','btn-primary')}</div>`):`<div class="grid-2">${box(`<span class="mini-label">Choose an Employee</span><label class="field">Person<select id="person-select">${people.map(p=>`<option value="${p.id}" ${p.id===person.id?'selected':''}>${esc(p.name)} · ${esc(p.position)}</option>`).join('')}</select></label><div class="cap-card"><strong>${esc(person.position)} / ${esc(person.dept)}</strong><small>Position target ≤ department ceiling ≤ business ceiling ≤ Digital AI</small><div class="bar"><i style="width:70%"></i></div></div><div class="button-row" style="margin-top:17px">${link('assessment','Open baseline assessment','btn-outline btn-small')}${link('path','See position path','btn-light btn-small')}</div>`)}${box(`<span class="mini-label">Recommended next course</span><h2 class="panel-title" style="margin-top:11px">${esc(courseName(recommended(person)))}</h2><p class="panel-desc">Basic lessons are fully open in the free trial. The recommendation follows the first confirmed gap in this position's target.</p>${link(`course/${recommended(person)}`,'Review course →','btn-primary')}<div class="divider"></div><span class="small muted">${person.assessed?`${gapCount(person)} confirmed gap(s); unconfirmed domains remain pending.`:'Complete the baseline assessment before interpreting gaps.'}</span>`)} </div>${box(`<div class="section-subhead" style="margin-top:0"><div><h2>Current → required</h2><p>Six-domain summary, with position-specific targets.</p></div>${badge(person.assessed?'Baseline measured':'Assessment pending',person.assessed?'green':'coral')}</div>${gapPanel(person)}`)}${state.role==='manager'?box(`<span class="mini-label">Manager recommendation</span><h2 class="panel-title" style="margin-top:10px">Propose a department change.</h2><p class="panel-desc">The Owner reviews and publishes any ceiling change. The Manager cannot publish it directly.</p><form data-form="proposal" class="inline-fields"><label class="field">Domain<select name="domain">${DOMAINS.map((d,i)=>`<option value="${i}">${esc(d)}</option>`).join('')}</select></label><label class="field">Suggested department ceiling<select name="level">${levelOptions(currentDept()?.ceiling[0]||1)}</select></label><button class="btn btn-outline" type="submit">Send proposal →</button></form>`):''}`}</div>`}
function assessmentPage(){const person=activePerson();return `${page('Baseline assessment','Measure before you recommend.','Choose a current level in each domain. This preview uses a short level selection; the production assessment will use actual questions and scoring.')}${!person?box(`<div class="empty-state"><h2>Invite an Employee first.</h2>${link('people','Go to people','btn-primary')}</div>`):box(`<span class="mini-label">${esc(person.name)} · ${esc(person.position)}</span><h2 class="panel-title" style="margin-top:10px">Six domains, one starting point.</h2><p class="panel-desc">Select “Not confirmed” if there is no measured result. It will remain pending in the gap view.</p><form data-form="assessment">${DOMAINS.map((d,i)=>`<label class="field">${esc(d)}<select name="domain-${i}">${levelOptions(person.current?.[i]||0)}</select></label>`).join('')}<button class="btn btn-primary" type="submit">Save baseline and see gap →</button></form>`)} `}
function employeeHome(){const person=employee();if(!person)return `${page('Employee learning','Your learning space','An Employee invitation is needed before a personal path can open.')}${box(`<div class="empty-state"><h2>No Employee in this sample yet.</h2><p>Switch to Owner and invite someone by department and position.</p>${link('people','Open people','btn-primary')}</div>`)}`;const rec=recommended(person),en=enrollment(rec,person),complete=en?.lessons.filter(Boolean).length||0;return `<div class="stack"><section class="employee-hero"><div><span class="eyebrow">${esc(person.name)} · ${esc(person.position)}</span><h1>One useful step <span style="color:#3448cf">today.</span></h1><p>Your path connects a measured starting point to the target your business set for ${esc(person.position)} in ${esc(person.dept)}.</p><div class="button-row">${link(!person.assessed?'assessment':`course/${en?.courseId||rec}`,!person.assessed?'Take baseline →':en?'Continue course →':'Explore next course →','btn-primary')}${link('path','See my path','btn-outline')}</div></div><img src="${ART}" alt="Abstract blue glass learning route with coral bridge"></section><div class="grid-3">${box(`<span class="mini-label">Your next move</span><h2 class="panel-title" style="margin-top:13px">${esc(courseName(en?.courseId||rec))}</h2><p class="panel-desc">${en?`${complete} of 3 lessons completed. Your final course assignment follows the learning check.`:'A Basic course is open in full for your business.'}</p><div class="bar"><i style="width:${complete/3*100}%"></i></div><div style="margin-top:18px">${link(`course/${en?.courseId||rec}`,en?'Continue learning ↗':'Open course ↗','btn-outline btn-small')}</div>`)}${box(`<span class="mini-label">Current → target</span><h2 class="panel-title" style="margin-top:13px">${gapCount(person)} measured gap${gapCount(person)===1?'':'s'}</h2><p class="panel-desc">Your position target is visible alongside your confirmed baseline. Missing results are kept pending.</p>${link('path','Explore my path ↗','btn-outline btn-small')}`)}${box(`<span class="mini-label">Practice and evidence</span><h2 class="panel-title" style="margin-top:13px">A clear final task.</h2><p class="panel-desc">After every course, submit evidence against visible criteria. Your Manager makes the final decision.</p>${link('assignment','See course assignment ↗','btn-outline btn-small')}`)}</div><div class="grid-2">${box(`<span class="mini-label">The road ahead</span><h2 class="panel-title" style="margin-top:10px">What happens next?</h2><div class="timeline"><div><i></i><time>01</time><span><strong>Understand your gap</strong><p>Baseline level beside ${esc(person.position)} target.</p></span></div><div><i></i><time>02</time><span><strong>Learn in context</strong><p>Basic fully open; higher courses need an assigned seat.</p></span></div><div><i></i><time>03</time><span><strong>Show your work</strong><p>Manager reviews the course's final assignment.</p></span></div></div>`)}${box(`<span class="mini-label">Your role target</span><h2 class="panel-title" style="margin-top:10px">${esc(person.position)}</h2><p class="panel-desc">This is your position path, within the ${esc(person.dept)} ceiling. Other departments and positions do not appear in your learning route.</p>${DOMAINS.map((d,i)=>`<div class="member-row"><div style="flex:1"><strong>${esc(d)}</strong><small>${person.current?.[i]?`Current L${person.current[i]}`:'Current pending'}</small></div>${badge(`Target L${position(person)?.target[i]||0}`)}</div>`).join('')}</div>`)}</div>`}
function pathPage(){const person=employee();if(!person)return employeeHome();const target=position(person)?.target||[];return `${page('My position path',`A route built for ${esc(person.position)}.`,`Your tested current level and the business target travel together. Each confirmed gap points to an eligible course.`)}<div class="stack">${box(`<span class="mini-label">Capability comparison</span><h2 class="panel-title" style="margin-top:10px">Where I am → what my role needs.</h2>${gapPanel(person)}`)}${box(`<span class="mini-label">Course ladder</span><h2 class="panel-title" style="margin-top:10px">Learn in the right order.</h2><p class="panel-desc">Basic is fully free. Intermediate and Advanced need the prior level and an Owner-assigned seat.</p>${DOMAINS.filter((d,i)=>target[i]>0).map(d=>{const i=DOMAINS.indexOf(d),base=courseId(i,1);return `<div class="path-step"><span class="node">${i+1}</span><div><strong>${esc(d)} · ${LEVEL[target[i]]} target</strong><small>${person.current?.[i]?`Current L${person.current[i]} → L${target[i]} target`:'Current pending → assessment needed'} · ${approved(base,person)?'Basic approved':'Start with Basic'}</small></div>${link(`course/${base}`,'Open path ↗','btn-outline btn-small')}</div>`}).join('')}`)}</div>`}
let filterTier='all',filterDomain='all';
function catalogPage(){const d=Number(filterDomain);const items=DOMAINS.flatMap((name,domain)=>[1,2,3].map(tier=>({name,domain,tier,course:courseId(domain,tier)}))).filter(item=>(filterTier==='all'||String(item.tier)===filterTier)&&(filterDomain==='all'||item.domain===d));return `${page('Course collection','The right course, at the right time.','Every Basic course is free in full. Owners can review higher-level outlines and a sample lesson before buying seats for their team.')}${box(`<div class="inline-fields"><label class="field">Level<select id="catalog-tier"><option value="all">All levels</option>${TIERS.map((t,i)=>`<option value="${i+1}" ${filterTier===String(i+1)?'selected':''}>${t}</option>`).join('')}</select></label><label class="field">Domain<select id="catalog-domain"><option value="all">All six domains</option>${DOMAINS.map((name,i)=>`<option value="${i}" ${filterDomain===String(i)?'selected':''}>${esc(name)}</option>`).join('')}</select></label></div>`)}<div style="height:16px"></div><div class="course-grid">${items.map(item=>`<article class="course-card"><div class="course-art"><span>${esc(SHORT[item.domain].toUpperCase())}</span><b>${String(item.domain+1).padStart(2,'0')}</b></div><div class="button-row" style="margin-bottom:12px"><span class="mini-label">${esc(TIERS[item.tier-1])}</span>${badge(item.tier===1?'Free full access':state.purchases[item.course]?'Seat purchased':'Paid access',item.tier===1?'green':state.purchases[item.course]?'green':'gray')}</div><h3>${esc(item.name)}</h3><p>${item.tier===1?'Build a practical foundation and submit a final assignment.':'Read the outline and sample lesson; unlock the full course with an assigned seat.'}</p><div class="button-row">${link(`course/${item.course}`,'View course →','btn-outline btn-small')}</div></article>`).join('')}</div>`}
function lessonsFor(course){const {domain,tier}=parseCourse(course);const name=DOMAINS[domain];return [{title:`Understand ${name.toLowerCase()} at work`,body:`Learn the core concepts behind ${name.toLowerCase()} at the ${TIERS[tier-1].toLowerCase()} level. Connect each idea to a real task in your position.`,callout:'A useful skill has a context, an action and a result you can explain.'},{title:'Make a reliable decision',body:`Work through a short ${name.toLowerCase()} scenario. Identify the source, choose an appropriate action and explain why it fits the situation.`,callout:'Keep a record of the evidence behind your choice.'},{title:'Apply it in your role',body:`Use ${name.toLowerCase()} in a task that matches your position. Prepare a result your Manager can inspect against the course criteria.`,callout:'Finish the learning check before submitting the final course assignment.'}]}
function coursePage(value){const course=parseCourse(value),cid=courseId(course.domain,course.tier),person=employee(),en=enrollment(cid,person),basic=course.tier===1,purchased=Number(state.purchases[cid]||0)>0,canRead=basic||purchased&&Boolean(en),owner=state.role==='owner',prereq=courseEligible(cid,person);const unlocked=owner?(basic||purchased):canRead;const lessons=lessonsFor(cid);return `<div class="stack"><section class="course-hero"><div><span class="eyebrow">${basic?'Free foundation':`${TIERS[course.tier-1]} · seat required`}</span><h1>${esc(DOMAINS[course.domain])}</h1><p>Three focused lessons, one learning check and a final assignment reviewed by a department Manager. ${basic?'All Basic content is open in full.':'The outline and first sample lesson are visible before purchase.'}</p><div class="button-row">${state.role==='employee'&&canRead?link(`lesson/${cid}/0`,en?'Continue lessons →':'Start learning →','btn-primary'):owner?basic?`<button class="btn btn-primary" data-action="assign-course" data-course="${cid}">Assign free course →</button>`:purchased?`<button class="btn btn-primary" data-action="assign-course" data-course="${cid}">Assign purchased seat →</button>`:`<button class="btn btn-primary" data-action="buy-seat" data-course="${cid}">Simulate seat purchase →</button>`:link('catalog','Browse courses','btn-outline')}</div></div><img src="${ARCH}" alt="Abstract connected blue capability forms"></section>${!basic?notice(owner?`Review this outline and sample before buying. ${purchased?'A simulated seat is available to assign.':'Full lessons remain locked until a seat is purchased.'}`:canRead?'An Owner-assigned seat opens the full course for you.':'Full lessons require a purchased seat assigned by your Owner.','warning'):notice('All Basic lessons are fully available during the free business trial.','success')}<div class="grid-2">${box(`<span class="mini-label">What you will be able to do</span><h2 class="panel-title" style="margin-top:10px">A practical course outcome.</h2><p class="panel-desc">Explain the idea, apply it to your role and produce evidence a Manager can inspect.</p><div class="rubric"><div><b>01</b> Trace the source or context.</div><div><b>02</b> Show a checkable decision or calculation.</div><div><b>03</b> Explain the next action and why it fits.</div></div>`)}${box(`<span class="mini-label">Access and progress</span><h2 class="panel-title" style="margin-top:10px">${basic?'Free in full':purchased?'Seat purchased':'Preview before purchase'}</h2><p class="panel-desc">${basic?'No checkout and no paid seat are required.':purchased?'Purchased seats can be assigned to eligible Employees.':'The first lesson is a sample. The rest opens after purchase and seat assignment.'}</p><div class="button-row">${badge(en?`${en.lessons.filter(Boolean).length}/3 lessons`:basic?'Ready to start':'Outline available',en?'green':'gray')}${!prereq?badge('Prior level required','coral'):''}</div>${owner&&purchased?`<form data-form="assign-paid" style="margin-top:16px"><input type="hidden" name="course" value="${cid}"><label class="field">Assign a seat to<select name="employee">${state.employees.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.position)}</option>`).join('')}</select></label><button class="btn btn-outline btn-small" type="submit">Assign seat</button></form>`:''}`)}</div>${box(`<span class="mini-label">Course outline</span><h2 class="panel-title" style="margin-top:10px">Three lessons. A real result.</h2>${lessons.map((lesson,i)=>`<div class="member-row"><span class="avatar">0${i+1}</span><div><strong>${esc(lesson.title)}</strong><small>${i===0||unlocked?'Lesson content available':'Outline visible · content locked'}</small></div>${i===0||unlocked?link(`lesson/${cid}/${i}`,i===0&&!unlocked?'Sample ↗':'Open ↗','btn-outline btn-small'):badge('Locked','gray')}</div>`).join('')}`)}${!basic?box(`<span class="mini-label">Before buying</span><h2 class="panel-title" style="margin-top:10px">What the Owner can review.</h2><p class="panel-desc">Course outcomes, all lesson titles, the first sample lesson and the final assignment criteria. Learner feedback will appear here only when verified reviews exist.</p>${notice('No invented ratings or testimonials are shown in this preview.')}`):''}</div>`}
function lessonPage(value,index){const c=parseCourse(value),cid=courseId(c.domain,c.tier),lessons=lessonsFor(cid),n=Math.min(2,Math.max(0,Number(index)||0)),en=enrollment(cid),basic=c.tier===1,owner=state.role==='owner';const purchased=Number(state.purchases[cid]||0)>0;const canAccess=basic||Boolean(en)||owner&&(n===0||purchased);const full=basic||Boolean(en)||owner&&purchased;if(!canAccess)return `${page('Lesson locked','A seat is needed.','The Owner can preview the outline and first sample lesson before buying.')}${link(`course/${cid}`,'Back to course','btn-outline')}`;return `<div class="stack"><div class="button-row">${link(`course/${cid}`,'← Course overview','btn-ghost btn-small')}${badge(`${DOMAINS[c.domain]} · ${TIERS[c.tier-1]}`)}</div><div class="lesson-layout"><nav class="surface lesson-list" aria-label="Course lessons">${lessons.map((lesson,i)=>`<a class="${i===n?'active':''}" href="#/${full||i===0?`lesson/${cid}/${i}`:`course/${cid}`}"><b>0${i+1}</b> ${esc(lesson.title)}</a>`).join('')}</nav><article class="surface lesson-content"><span class="eyebrow">Lesson 0${n+1} of 03 ${!full?'· sample preview':''}</span><h1>${esc(lessons[n].title)}</h1><p>${esc(lessons[n].body)}</p><div class="callout"><strong>Put it to work.</strong><br>${esc(lessons[n].callout)}</div><h2 class="panel-title">Try this in your context</h2><p>Think of one task in ${esc(employee()?.position||'your position')} that uses this idea. What information would make the result easy for another person to verify?</p>${full&&state.role==='employee'?`<div class="button-row" style="margin-top:28px"><button class="btn btn-primary" data-action="complete-lesson" data-course="${cid}" data-index="${n}">${en?.lessons[n]?'Lesson completed ✓':'Mark lesson complete →'}</button>${n<2?link(`lesson/${cid}/${n+1}`,'Next lesson','btn-outline'):link('assignment','Go to final check','btn-outline')}</div>`:notice('This is a sample lesson. Full paid content opens after a seat is purchased and assigned.','warning')}</article></div></div>`}
function effectiveStatus(en){if(en.status==='retry-wait'&&now()>=en.releaseAt&&now()<=en.deadlineAt)return 'retry-ready';if(en.status==='retry-wait'&&now()>en.deadlineAt)return 'deadline-missed';return en.status}
function assignmentPage(){const person=employee(),items=state.enrollments.filter(e=>e.employeeId===person?.id),requested=route().split('/')[1],en=items.find(e=>e.courseId===requested)||items.find(e=>!['approved','flagged'].includes(e.status))||items[items.length-1];if(!en)return `${page('Practice and evidence','Your final course assignment','A course opens the final assignment after its lessons and learning check.')}${box(`<div class="empty-state"><div class="icon">◎</div><h2>Choose a course first.</h2><p>Basic courses are free in full. Complete the lessons before submitting final work.</p>${link('catalog','Browse courses →','btn-primary')}</div>`)}`;const status=effectiveStatus(en),allLessons=en.lessons.every(Boolean);return `${page('Course practice',`Show what you learned.`,`Your Manager reviews the final assignment after every course. AI suggestions support the review; the Manager makes the final decision.`,badge(`${en.attempts.length}/2 submissions`))}<div class="stack">${box(`<span class="mini-label">${esc(courseName(en.courseId))} · final assignment</span><h2 class="panel-title" style="margin-top:10px">Create a traceable work note.</h2><p class="panel-desc">Describe a real task in ${esc(person?.position||'your position')}. Include the source, a checkable action or calculation, and a conclusion with the next step.</p><div class="rubric"><div><b>01</b> Source or context is traceable.</div><div><b>02</b> Decision or calculation can be checked.</div><div><b>03</b> Conclusion and next action are supported.</div></div>`)}${!allLessons?box(`${notice(`Complete all three lessons first. ${en.lessons.filter(Boolean).length}/3 done.`, 'warning')}<div class="button-row" style="margin-top:17px">${link(`lesson/${en.courseId}/${Math.max(0,en.lessons.findIndex(v=>!v))}`,'Continue lessons →','btn-primary')}</div>`):!en.finalCheck?box(`<span class="mini-label">Learning check</span><h2 class="panel-title" style="margin-top:10px">One quick check before evidence.</h2><p class="panel-desc">Which approach makes a workplace result easier for a Manager to verify?</p><form data-form="final-check"><label class="field">Choose an answer<select name="answer" required><option value="">Select one</option><option value="skip">Submit without a source</option><option value="trace">Show source, action and conclusion</option><option value="claim">Claim the result is correct without explaining</option></select></label><button class="btn btn-primary" type="submit">Check answer</button></form>`):status==='pending'?box(notice('Your work is with your Manager. You will see the decision and reason here. The next level stays locked until approval.')):status==='approved'?box(`${notice('Your Manager approved this course. The cycle is now in the Owner report. A next eligible level opens when a seat is assigned.','success')}${link('path','See next path','btn-outline')}`):status==='flagged'?box(notice('Two submissions did not meet the rubric. Your Manager sees a support flag and decides coaching, a fresh learning cycle or a pause. No next level is released.','warning')):status==='retry-wait'?box(`${notice(`Your first submission was not yet approved. The second opens after ${state.cooldownHours} hours; it is due within ${state.deadlineDays} days after opening.`,`warning`)}<p class="small">Manager feedback: ${esc(en.attempts.at(-1)?.reason||'Review the criteria and strengthen your evidence.')}</p><button class="btn btn-outline btn-small" data-action="advance-time">Advance preview time to the second submission</button>`):status==='deadline-missed'?box(notice('The second submission deadline passed in this preview. The Manager should arrange support before the path continues.','warning')):box(`<span class="mini-label">${en.attempts.length?'Second and final submission':'Submission 1 of 2'}</span><h2 class="panel-title" style="margin-top:10px">Make your evidence easy to inspect.</h2>${en.attempts.length?notice(`Your final submission is due ${date(en.deadlineAt)}. ${Math.max(0,Math.ceil((en.deadlineAt-now())/86400000))} day(s) remain.`, 'warning'):''}<form data-form="assignment"><input type="hidden" name="course" value="${en.courseId}"><label class="field">Evidence note<textarea name="evidence" required minlength="30" placeholder="Name the source, show your action or calculation, then explain the conclusion and next step."></textarea><span class="field-hint">At least 30 characters. Files are represented by this note in the local preview.</span></label><button class="btn btn-primary" type="submit">Submit ${en.attempts.length?'final attempt':'assignment'} →</button></form>`)}</div>`}
function managerHome(){const dept=currentDept(),people=state.employees.filter(p=>p.dept===dept?.name),queue=state.enrollments.filter(e=>people.some(p=>p.id===e.employeeId)&&['pending','flagged'].includes(e.status));return `${page(`Team Manager · ${esc(dept?.name||'Accounting')}`,'Focus on the work that needs you.','One department scope: measured gaps, course assignments and support signals.',link('review','Open review queue','btn-primary'))}<div class="stack">${box(`<span class="mini-label">Your department today</span><h2>Make the next decision clear.</h2><p>Read the course criteria and submitted evidence. Use AI suggestions as a reference, then record your own verdict and reason.</p><div class="button-row">${link('review','Review assignments →','btn-primary')}${link('gap','See team capability →','btn-outline')}</div>`,'flow-banner')}<div class="grid-3"><div class="surface kpi"><span>Team Employees</span><strong>${people.length}</strong><small>Only ${esc(dept?.name||'Accounting')}</small></div><div class="surface kpi"><span>Waiting for decision</span><strong>${queue.filter(e=>e.status==='pending').length}</strong><small>Final assignments</small></div><div class="surface kpi"><span>Support flags</span><strong>${queue.filter(e=>e.status==='flagged').length}</strong><small>After two unsuccessful submissions</small></div></div><div class="grid-2">${box(`<h2 class="panel-title">Course assignment queue</h2><p class="panel-desc">The final assignment is separate from ongoing workplace practice.</p>${queue.length?queue.map(e=>{const p=state.employees.find(x=>x.id===e.employeeId);return `<div class="member-row"><span class="avatar">${esc(p?.name.split(' ').map(x=>x[0]).join('')||'E')}</span><div><strong>${esc(p?.name||'Employee')}</strong><small>${esc(courseName(e.courseId))} · ${e.attempts.length}/2 submissions</small></div>${badge(e.status==='flagged'?'Needs support':'Review now',e.status==='flagged'?'coral':'gray')}</div>`}).join(''):`<p class="small">No final assignments waiting in this department.</p>`}<div style="margin-top:15px">${link('review','Open queue','btn-outline btn-small')}</div>`)}${box(`<h2 class="panel-title">Team capability</h2><p class="panel-desc">Read each measured baseline beside the target for their position.</p>${people.map(p=>`<div class="member-row"><span class="avatar">${esc(p.name.split(' ').map(x=>x[0]).join(''))}</span><div><strong>${esc(p.name)}</strong><small>${esc(p.position)} · ${gapCount(p)} confirmed gaps</small></div>${badge(p.assessed?'Measured':'Pending',p.assessed?'green':'gray')}</div>`).join('')||'<p class="small">No Employees in this department yet.</p>'}<div style="margin-top:15px">${link('gap','Inspect team gaps','btn-outline btn-small')}</div>`)}</div></div>`}
function aiSuggestion(evidence){const text=String(evidence||'').toLowerCase();const checks=[/source|data|record|ledger|report/.test(text),/check|calculate|compare|verify|formula/.test(text),/conclusion|next|action|recommend/.test(text)];return {checks,summary:checks.every(Boolean)?'The note appears to name a source, a checkable action and a next step. Inspect the actual work before deciding.':'The note may need clearer source, checkable action or next step. Inspect the actual work before deciding.'}}
function reviewPage(){const dept=currentDept(),people=state.employees.filter(p=>p.dept===dept?.name),queue=state.enrollments.filter(e=>people.some(p=>p.id===e.employeeId)&&['pending','flagged','retry-wait'].includes(e.status));return `${page(`Manager review · ${esc(dept?.name||'Accounting')}`,'Make a decision with evidence in view.','One final assignment per course and learner. AI suggestions are advisory; the Manager records the final decision and reason.',badge(`${queue.filter(e=>e.status==='pending').length} to review`))}<div class="stack">${queue.length?queue.map(e=>{const p=state.employees.find(x=>x.id===e.employeeId),attempt=e.attempts.at(-1),hint=aiSuggestion(attempt?.evidence);return box(`<div class="button-row" style="justify-content:space-between"><span class="mini-label">${esc(p?.name||'Employee')} / ${esc(p?.position||'Position')} / ${esc(courseName(e.courseId))}</span>${badge(e.status==='flagged'?'Support flag':e.status==='pending'?'Decision needed':'Awaiting retry',e.status==='flagged'?'coral':e.status==='pending'?'gray':'green')}</div><h2 class="panel-title" style="margin-top:15px">Submission ${e.attempts.length} of 2</h2><p class="panel-desc">${e.status==='flagged'?'Two unsuccessful submissions. Choose coaching, a fresh learning cycle or a pause.':e.status==='retry-wait'?'The Employee is reviewing feedback before the timed final submission.':'Read the Employee’s note against all three course criteria.'}</p>${attempt?`<div class="surface pad" style="background:#fbfcff;box-shadow:none"><span class="mini-label">Submitted evidence</span><p style="margin:10px 0 0;white-space:pre-wrap">${esc(attempt.evidence)}</p></div><div class="grid-2" style="margin-top:14px"><div class="rubric"><div><b>01</b> Traceable source or context ${hint.checks[0]?'✓':'·'}</div><div><b>02</b> Checkable action ${hint.checks[1]?'✓':'·'}</div><div><b>03</b> Supported next step ${hint.checks[2]?'✓':'·'}</div></div><div class="ai-box"><h3>✦ AI review suggestion · sample</h3><p>${hint.summary}</p><small>This text check is illustrative. It cannot inspect a real attachment or make the verdict.</small></div></div>`:''}${e.status==='pending'?`<form data-form="review" style="margin-top:18px"><input type="hidden" name="employee" value="${e.employeeId}"><input type="hidden" name="course" value="${e.courseId}"><div class="inline-fields"><label class="field">Manager decision<select name="decision" required><option value="">Select a decision</option><option value="pass">Approve course</option><option value="fail">Not yet · needs revision</option></select></label><label class="field">Reason for the Employee<textarea name="reason" required minlength="10" placeholder="Reference a criterion and the next step."></textarea></label></div><button class="btn btn-primary" type="submit">Record final decision →</button></form>`:e.status==='flagged'?`<div class="button-row" style="margin-top:16px"><button class="btn btn-outline btn-small" data-action="support" data-id="${e.employeeId}|${e.courseId}" data-kind="Coaching arranged">Arrange coaching</button><button class="btn btn-outline btn-small" data-action="support" data-id="${e.employeeId}|${e.courseId}" data-kind="Fresh learning cycle recommended">Recommend fresh cycle</button><button class="btn btn-outline btn-small" data-action="support" data-id="${e.employeeId}|${e.courseId}" data-kind="Learning paused">Pause path</button></div>${e.support?notice(`Support action: ${esc(e.support)}`,'success'):''}`:notice(`Second submission opens after ${state.cooldownHours} hours and is due ${state.deadlineDays} days later.`,'warning')}`)}).join(''):box(`<div class="empty-state"><div class="icon">◎</div><h2>Nothing to decide yet.</h2><p>When an Employee submits a final course assignment, it appears here for their department Manager.</p>${link('manager','Back to team','btn-outline')}</div>`)}${box(`<span class="mini-label">Separate evidence track</span><h2 class="panel-title" style="margin-top:10px">Practical tasks are not final course assignments.</h2><p class="panel-desc">Workplace evidence can be reviewed during learning. The two-submission rule applies only to the final assignment after each course.</p>`)}</div>`}
function reportPage(){const visible=state.role==='manager'?state.enrollments.filter(e=>state.employees.find(p=>p.id===e.employeeId)?.dept===currentDept()?.name):state.enrollments;const complete=visible.filter(e=>e.status==='approved'),inProgress=visible.filter(e=>e.status!=='approved'),graded=visible.filter(e=>e.attempts.length),participants=new Set(visible.map(e=>e.employeeId)).size,attempts=visible.reduce((sum,e)=>sum+e.attempts.length,0),activeCourse=complete.at(-1);return `${page('Course-cycle intelligence','See the full journey, not just a score.','Once a Manager approves a final assignment, the report connects the business target, baseline, learning activity, review and next step.',complete.length?`<button class="btn btn-outline" data-action="print">Print report ↗</button>`:'')}<div class="stack">${!complete.length?box(`<div class="empty-state"><div class="icon">▣</div><h2>Your first course report is taking shape.</h2><p>Complete a Basic course and have its final assignment approved by the department Manager. This report will then show the process from baseline to decision.</p><div class="button-row" style="justify-content:center">${link('gap','See capability gap','btn-outline')}${link('catalog','Open courses','btn-primary')}</div></div>`):`<section class="surface report-cover"><div><span class="eyebrow">${esc(state.org)} · course-cycle report</span><h1>A completed learning cycle, in context.</h1><p>${complete.length} approved course cycle${complete.length===1?'':'s'} across ${participants} learner${participants===1?'':'s'}. Includes Basic trial courses and any later purchased courses using the same reporting model.</p></div><div class="report-mark">${complete.length.toString().padStart(2,'0')}</div></section><div class="grid-4"><div class="report-metric"><span>Approved courses</span><strong>${complete.length}</strong><small class="muted">Manager decision recorded</small></div><div class="report-metric"><span>Learners in cycle</span><strong>${participants}</strong><small class="muted">Across the visible scope</small></div><div class="report-metric"><span>Submissions reviewed</span><strong>${attempts}</strong><small class="muted">Including second attempts</small></div><div class="report-metric"><span>Courses underway</span><strong>${inProgress.length}</strong><small class="muted">May join future reports</small></div></div>${complete.map(e=>{const p=state.employees.find(x=>x.id===e.employeeId),target=position(p)?.target||[],c=parseCourse(e.courseId),last=e.attempts.at(-1);return `<div class="grid-2">${box(`<span class="mini-label">${esc(courseName(e.courseId))} · ${c.tier===1?'Free trial':'Purchased access'}</span><h2 class="panel-title" style="margin-top:10px">${esc(p?.name||'Employee')} · ${esc(p?.position||'Position')}</h2><p class="panel-desc">${esc(p?.dept||'Department')} · assigned ${date(e.assignedAt||now())} · approved ${date(last?.reviewedAt||now())}</p><div class="rubric"><div><b>01</b> Baseline measured: ${p?.current?.filter(v=>v>0).length||0}/6 domains confirmed.</div><div><b>02</b> Position target: ${target.filter(v=>v>0).length}/6 domains included.</div><div><b>03</b> Learning: ${e.lessons.filter(Boolean).length}/3 lessons and final check.</div><div><b>04</b> Final assignment: approved after ${e.attempts.length} submission${e.attempts.length===1?'':'s'}.</div></div>`)}${box(`<span class="mini-label">Evidence and decision</span><h2 class="panel-title" style="margin-top:10px">What the Manager confirmed.</h2><p class="panel-desc">${esc(last?.reason||'The course assignment met the criteria.')}</p><div class="notice success">Approved final assignment in ${esc(courseName(e.courseId))}. This is evidence of course completion, not a new measured baseline.</div><div class="divider"></div><h3 class="panel-title" style="font-size:17px">Recommended next step</h3><p class="small">Reassess the target skill after workplace practice. ${c.tier<3?`The ${TIERS[c.tier]} course may be considered when prerequisites and a seat are available.`:'Continue applying the skill in role-specific work.'}</p>`)}</div>`}).join('')}${box(`<div class="section-subhead" style="margin-top:0"><div><h2>Current levels beside required levels.</h2><p>A course pass does not overwrite a baseline test result.</p></div></div>${gapPanel(state.employees.find(p=>p.id===activeCourse.employeeId))}`)}`}<div class="grid-2">${box(`<span class="mini-label">Process timeline</span><h2 class="panel-title" style="margin-top:10px">The decisions along the way.</h2><div class="timeline">${state.events.slice(0,8).map(item=>`<div><i></i><time>${date(item.at)}</time><span><strong>${esc(item.title)}</strong><p>${esc(item.detail)}</p></span></div>`).join('')||`<p class="small">Activity appears here as the team moves through the flow.</p>`}</div>`)}${box(`<span class="mini-label">Keep the same model as you grow</span><h2 class="panel-title" style="margin-top:10px">The next course joins this story.</h2><p class="panel-desc">When the Owner buys and assigns a higher-level course, it uses the same lesson, final assignment, Manager decision and report cycle. Purchased access changes eligibility; it does not change the learning evidence model.</p><div class="button-row">${link('catalog','Explore next course →','btn-primary')}${link('gap','Revisit capability →','btn-outline')}</div><div class="divider"></div><p class="report-note">This preview calculates report figures from local sample interactions. Production reporting will need validated assessment and learning records.</p>`)}</div></div>`}
function notFound(){return `${page('Page not found','This path is not in the preview.','Return to the beginning of the product journey.')}${link('welcome','Go to landing','btn-primary')}`}
function render(){let path=route(),parts=path.split('/');if(!['welcome','register','login','verify'].includes(parts[0])&&!state.verified){if(!['catalog','course'].includes(parts[0])){location.hash='#/login';path='login';parts=['login']}}let content;switch(parts[0]){case 'welcome':content=landing();break;case 'register':case 'verify':case 'login':content=authPage(parts[0]);break;case 'owner':content=ownerHome();break;case 'setup':content=setupPage();break;case 'people':content=peoplePage();break;case 'gap':content=gapPage();break;case 'assessment':content=assessmentPage();break;case 'employee':content=employeeHome();break;case 'path':content=pathPage();break;case 'catalog':content=catalogPage();break;case 'course':content=coursePage(parts[1]);break;case 'lesson':content=lessonPage(parts[1],parts[2]);break;case 'assignment':content=assignmentPage();break;case 'manager':content=managerHome();break;case 'review':content=reviewPage();break;case 'report':content=reportPage();break;default:content=notFound()}document.title=`DigiTalent Pulse · ${parts[0][0].toUpperCase()+parts[0].slice(1)}`;$('#app').innerHTML=shell(parts[0],content);save()}
function publishBlueprint(){for(const dept of state.departments){if(!dept.positions.length)return toast(`${dept.name} needs a position.`);for(let i=0;i<6;i++){if(dept.ceiling[i]>state.business[i])return toast(`${dept.name}: department ceiling exceeds business in ${DOMAINS[i]}.`);for(const pos of dept.positions)if(pos.target[i]>dept.ceiling[i])return toast(`${pos.name}: position target exceeds department in ${DOMAINS[i]}.`)}}state.published=true;event('Capability blueprint published',`${state.departments.length} department(s) and their position targets are ready.`);save();go('people');toast('Blueprint published. Create Managers and invite Employees.')}
function addEmployee(name,email,deptName,positionName){if(!state.published)return 'Publish the blueprint first.';if(state.employees.length>=10)return 'The free trial has reached 10 Employee seats.';const dept=department(deptName);if(!dept)return 'Department not found.';if(!dept.positions.some(p=>p.name===positionName))return 'Position does not belong to the department.';if(!dept.manager)return `Assign a Manager to ${deptName} first.`;if(state.employees.some(p=>p.email.toLowerCase()===email.toLowerCase()))return 'Email already exists.';state.employees.push({id:id(),name,email,dept:deptName,position:positionName,current:[0,0,0,0,0,0],assessed:false});event('Employee routed to a position',`${name} joined ${deptName} / ${positionName}.`);return ''}
function startEnrollment(cid,person){if(!person)return toast('Add an Employee first.');if(!courseEligible(cid,person))return toast('Approve the prior course level before assigning this one.');let en=enrollment(cid,person);if(en)return toast('This Employee is already in the course.');const c=parseCourse(cid);if(c.tier>1){const assigned=state.enrollments.filter(e=>e.courseId===cid).length;if(assigned>=Number(state.purchases[cid]||0))return toast('Buy another seat before assigning this course.')}state.enrollments.push({employeeId:person.id,courseId:cid,lessons:[false,false,false],finalCheck:false,attempts:[],status:'learning',releaseAt:null,deadlineAt:null,assignedAt:now()});event('Course assigned',`${person.name} began ${courseName(cid)}.`);save();toast(`${courseName(cid)} assigned to ${person.name}.`)}
function parseCsv(text){const rows=[],lines=String(text).replace(/^\uFEFF/,'').split(/\r?\n/).filter(line=>line.trim());function cells(line){const output=[];let value='',quoted=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"'&&quoted&&line[i+1]==='"'){value+='"';i++}else if(c==='"')quoted=!quoted;else if(c===','&&!quoted){output.push(value.trim());value=''}else value+=c}output.push(value.trim());return output}const header=cells(lines.shift()||'').map(x=>x.toLowerCase());for(const line of lines){const values=cells(line),raw=Object.fromEntries(header.map((key,i)=>[key,values[i]||'']));const row={email:raw.email||'',name:raw.full_name||'',dept:raw.department||'',position:raw.position||'',role:(raw.role||'EMPLOYEE').toUpperCase(),error:''};if(!row.email.includes('@')||!row.name)row.error='Missing name/email';else if(row.role!=='EMPLOYEE')row.error='Employee rows only';else if(!department(row.dept)?.positions.some(p=>p.name===row.position))row.error='Check department/position';else if(!department(row.dept)?.manager)row.error='Manager needed';else if(state.employees.some(p=>p.email.toLowerCase()===row.email.toLowerCase()))row.error='Already added';rows.push(row)}return rows}
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='role-switch'){state.role=t.value;save();go(rolePath(t.value))}else if(t.id==='setup-dept'){selectedDept=Number(t.value);selectedPosition=0;render()}else if(t.id==='setup-position'){selectedPosition=Number(t.value);render()}else if(t.id==='invite-dept'){const dept=department(t.value);$('#invite-position').innerHTML=dept?.positions.map(p=>`<option value="${esc(p.name)}">${esc(p.name)}</option>`).join('')||''}else if(t.id==='person-select'){selectedEmployeeId=t.value;render()}else if(t.id==='catalog-tier'){filterTier=t.value;render()}else if(t.id==='catalog-domain'){filterDomain=t.value;render()}else if(t.id==='cooldown'||t.id==='deadline'){const n=Number(t.value);if(!Number.isInteger(n)||n<1)return toast('Enter a positive whole number.');if(t.id==='cooldown')state.cooldownHours=Math.min(720,n);else state.deadlineDays=Math.min(90,n);state.published=false;save();toast('Timing changed. Publish the blueprint to confirm the policy.')}else if(t.dataset.cap){const i=Number(t.dataset.domain),value=Number(t.value),dept=state.departments[selectedDept],pos=dept.positions[selectedPosition];if(t.dataset.cap==='business'){if(state.departments.some(d=>d.ceiling[i]>value)){render();return toast('Lower the department ceiling first.')}state.business[i]=value}else if(t.dataset.cap==='department'){if(value>state.business[i]||dept.positions.some(p=>p.target[i]>value)){render();return toast('This level conflicts with the business or a position.')}dept.ceiling[i]=value}else{if(value>dept.ceiling[i]){render();return toast('Position target cannot exceed its department.')}pos.target[i]=value}state.published=false;save();render()}else if(t.id==='csv-file'&&t.files?.[0]){try{importRows=parseCsv(await t.files[0].text());$('#csv-preview').innerHTML=csvPreview()}catch{toast('Could not read the CSV file.')}}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-action]');if(!t)return;const action=t.dataset.action;if(action==='sample'){state=sample();save();go('owner')}else if(action==='verify'){state.verified=true;state.role='owner';event('Business trial activated','Owner email confirmed in this local preview; Basic access has no expiry.');save();go('setup')}else if(action==='publish')publishBlueprint();else if(action==='reset'){if(!confirm('Clear this browser-local sample and return to the landing page?'))return;state=fresh();importRows=[];save();go('welcome')}else if(action==='buy-seat'){const cid=t.dataset.course;state.purchases[cid]=(state.purchases[cid]||0)+1;event('Course seat purchase simulated',`${courseName(cid)} · one seat available for assignment.`);save();render();toast('Sample seat added. No payment was taken.')}else if(action==='assign-course'){const person=employee();if(!person)return toast('Add an Employee before assigning a course.');startEnrollment(t.dataset.course,person);render()}else if(action==='complete-lesson'){const cid=t.dataset.course,person=employee();if(!enrollment(cid,person))startEnrollment(cid,person);const en=enrollment(cid,person);if(!en)return;en.lessons[Number(t.dataset.index)]=true;save();render();toast('Lesson complete. Your progress is saved in this browser.')}else if(action==='advance-time'){state.timeOffsetHours+=state.cooldownHours+1;save();render();toast('Preview time advanced. The final submission is open.')}else if(action==='support'){const [person,cid]=String(t.dataset.id).split('|'),en=state.enrollments.find(x=>x.employeeId===person&&x.courseId===cid);if(!en)return;en.support=t.dataset.kind;event('Manager support action',`${t.dataset.kind} for ${courseName(cid)}.`);save();render()}else if(action==='accept-proposal'||action==='reject-proposal'){const p=state.proposals.find(x=>x.id===t.dataset.id);if(!p)return;if(action==='accept-proposal'){const dept=department(p.department);if(p.level>state.business[p.domain]||dept.positions.some(pos=>pos.target[p.domain]>p.level))return toast('The proposal conflicts with the business or a position. Adjust those levels first.');dept.ceiling[p.domain]=p.level;state.published=false;p.status='accepted';event('Manager proposal accepted into draft',`${p.department} / ${DOMAINS[p.domain]} ceiling updated.`)}else p.status='declined';save();render()}else if(action==='print')window.print()});
document.addEventListener('submit',e=>{const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();const type=form.dataset.form,data=new FormData(form),get=name=>String(data.get(name)||'').trim();if(type==='register'){state=fresh();state.org=get('org');state.ownerEmail=get('email');state.role='owner';save();go('verify')}else if(type==='login'){if(!state.verified)state=sample();state.role=get('role');save();go(rolePath(state.role))}else if(type==='manager'){const dept=department(get('department'));dept.manager=get('name');event('Department Manager assigned',`${dept.manager} now manages ${dept.name}.`);save();render();toast('Manager saved for this department.')}else if(type==='add-department'){const name=get('name');if(state.departments.some(d=>d.name.toLowerCase()===name.toLowerCase()))return toast('This department already exists.');state.departments.push({name,ceiling:state.business.map(v=>Math.min(v,1)),manager:'',positions:[{name:'Generalist',target:state.business.map(v=>Math.min(v,1))}]});selectedDept=state.departments.length-1;selectedPosition=0;state.published=false;save();render();toast('Department added. Set its ceiling and position targets.')}else if(type==='add-position'){const dept=state.departments[selectedDept],name=get('name');if(dept.positions.some(p=>p.name.toLowerCase()===name.toLowerCase()))return toast('This position already exists.');dept.positions.push({name,target:dept.ceiling.map(v=>Math.min(v,1))});selectedPosition=dept.positions.length-1;state.published=false;save();render()}else if(type==='invite'){const error=addEmployee(get('name'),get('email'),get('department'),get('position'));if(error)return toast(error);save();render();toast('Sample Employee added. No invitation was sent.')}else if(type==='assessment'){const person=activePerson();if(!person)return;person.current=DOMAINS.map((_,i)=>Number(get(`domain-${i}`)));person.assessed=true;event('Baseline assessment completed',`${person.name} now has a measured current-versus-position comparison.`);save();go(state.role==='employee'?'path':'gap')}else if(type==='proposal'){const domain=Number(get('domain')),level=Number(get('level')),dept=currentDept();if(level>state.business[domain]||dept.positions.some(p=>p.target[domain]>level))return toast('Suggested ceiling conflicts with a parent or position target.');state.proposals.push({id:id(),department:dept.name,domain,level,status:'pending'});save();render();toast('Proposal sent to Owner review.')}else if(type==='final-check'){if(get('answer')!=='trace')return toast('Try again: a source, checkable action and conclusion make evidence inspectable.');const en=state.enrollments.find(x=>x.employeeId===employee()?.id&&!x.finalCheck&&x.lessons.every(Boolean));if(!en)return toast('Complete lessons first.');en.finalCheck=true;event('Learning check passed',`${employee().name} completed the ${courseName(en.courseId)} learning check.`);save();render()}else if(type==='assignment'){const en=enrollment(get('course'));if(!en||!en.finalCheck||!en.lessons.every(Boolean))return toast('Finish the lessons and learning check first.');const status=effectiveStatus(en);if(!['learning','retry-ready'].includes(status)||en.attempts.length>=2)return toast('This submission is not open.');en.attempts.push({at:now(),evidence:get('evidence'),decision:null,reason:''});en.status='pending';event('Final assignment submitted',`${employee().name} submitted ${courseName(en.courseId)} · attempt ${en.attempts.length}/2.`);save();render();toast('Assignment sent to the department Manager in this preview.')}else if(type==='review'){const en=state.enrollments.find(x=>x.employeeId===get('employee')&&x.courseId===get('course'));if(!en||en.status!=='pending')return toast('This submission is no longer pending.');const attempt=en.attempts.at(-1),decision=get('decision'),reason=get('reason');if(!['pass','fail'].includes(decision)||reason.length<10)return toast('Choose a verdict and give a specific reason.');attempt.decision=decision;attempt.reason=reason;attempt.reviewedAt=now();if(decision==='pass'){en.status='approved';event('Course cycle approved',`${state.employees.find(p=>p.id===en.employeeId)?.name} completed ${courseName(en.courseId)}. The cycle report is ready.`)}else if(en.attempts.length===1){en.status='retry-wait';en.releaseAt=now()+state.cooldownHours*3600000;en.deadlineAt=en.releaseAt+state.deadlineDays*86400000;event('First submission needs revision',`${courseName(en.courseId)} · second attempt opens after ${state.cooldownHours} hours.`)}else{en.status='flagged';event('Two-fail support flag raised',`${courseName(en.courseId)} needs a Manager support decision.`)}save();render();toast(decision==='pass'?'Course approved. The cycle report is ready.':en.status==='flagged'?'Support flag raised for the Manager.':'Feedback recorded. The timed final submission is next.')}else if(type==='assign-paid'){const person=state.employees.find(p=>p.id===get('employee'));startEnrollment(get('course'),person);render()}});
window.addEventListener('hashchange',()=>{window.scrollTo(0,0);render()});
document.addEventListener('DOMContentLoaded',render);
document.addEventListener('click',e=>{
  const scrollLink=e.target.closest('a[href="#/welcome#how"],a[href="#/welcome#approach"]');
  if(scrollLink){e.preventDefault();go('welcome');requestAnimationFrame(()=>document.getElementById(scrollLink.hash.endsWith('how')?'how':'approach')?.scrollIntoView({behavior:'smooth'}));return}
  const button=e.target.closest('[data-action="commit-import"]');
  if(!button)return;
  let added=0;
  for(const row of importRows.filter(r=>!r.error)){
    const error=addEmployee(row.name,row.email,row.dept,row.position);
    if(error){row.error=error;continue}
    added++;
  }
  importRows=importRows.filter(row=>row.error);
  save();render();toast(`${added} sample Employee${added===1?'':'s'} added. No invitations were sent.`);
});
const reportCore=reportPage;
reportPage=function(){
  const content=reportCore();
  const rows=state.enrollments.filter(e=>state.role!=='manager'||state.employees.find(p=>p.id===e.employeeId)?.dept===currentDept()?.name);
  if(!rows.some(e=>e.status==='approved'))return content;
  const cohort=box(`<div class="section-subhead" style="margin-top:0"><div><h2>Every learner in the training cycle.</h2><p>Completed, in progress and waiting for a Manager decision appear together.</p></div>${badge(`${rows.length} course enrollment${rows.length===1?'':'s'}`)}</div><div class="table-scroll"><table class="data-table"><thead><tr><th>Employee and position</th><th>Course</th><th>Baseline</th><th>Learning</th><th>Manager outcome</th></tr></thead><tbody>${rows.map(e=>{const p=state.employees.find(x=>x.id===e.employeeId),status=effectiveStatus(e),label={approved:'Approved',pending:'Awaiting Manager',learning:'In progress','retry-wait':'Timed review','retry-ready':'Final attempt open',flagged:'Support needed','deadline-missed':'Deadline missed'}[status]||status;return `<tr><td><strong>${esc(p?.name||'Employee')}</strong><br><span class="dim">${esc(p?.dept||'Department')} · ${esc(p?.position||'Position')}</span></td><td>${esc(courseName(e.courseId))}<br><span class="dim">${parseCourse(e.courseId).tier===1?'Free Basic':'Purchased seat'}</span></td><td>${p?.assessed?`${gapCount(p)} confirmed gap(s)`:'Pending'}</td><td>${e.lessons.filter(Boolean).length}/3 lessons · ${e.finalCheck?'check passed':'check pending'}</td><td>${badge(label,status==='approved'?'green':status==='flagged'?'coral':'gray')}<br><span class="dim">${e.attempts.length}/2 submission(s)</span></td></tr>`}).join('')}</tbody></table></div><p class="report-note" style="margin:14px 0 0">A passed course assignment confirms course evidence. A new assessment is required to claim that a capability gap closed.</p>`,'report-cohort');
  return `${content}<div style="height:16px"></div>${cohort}`;
};
const lessonCore=lessonPage;
lessonPage=function(value,index){
  const html=lessonCore(value,index),course=parseCourse(value);
  if(state.role==='owner'&&(course.tier===1||Number(state.purchases[courseId(course.domain,course.tier)]||0)>0))return html.replace('This is a sample lesson. Full paid content opens after a seat is purchased and assigned.','Full lesson content is available in this Owner preview.');
  return html;
};
const courseCore=coursePage;
coursePage=function(value){
  const html=courseCore(value),course=parseCourse(value);
  let result=html;
  if(state.role==='owner'&&course.tier===1&&state.employees.length){const chooser=box(`<form data-form="assign-paid"><input type="hidden" name="course" value="${courseId(course.domain,1)}"><div class="inline-fields"><label class="field">Assign this free course to an Employee<select name="employee">${state.employees.map(p=>`<option value="${p.id}">${esc(p.name)} · ${esc(p.position)}</option>`).join('')}</select></label><div style="align-self:end;padding-bottom:15px"><button class="btn btn-outline" type="submit">Assign free course →</button></div></div></form>`,'basic-course-assignment');result=result.replace('</section>',`</section>${chooser}`)}
  if(state.role==='owner')result+=box(`<div class="section-subhead" style="margin-top:0"><div><span class="mini-label">Learner review preview</span><h2>How the course may feel in practice.</h2><p>Illustrative feedback for design review. Production should show verified course reviews only.</p></div>${badge('Sample feedback','gray')}</div><div class="grid-2"><article class="cap-card"><span class="mini-label">01 / Clarity</span><p style="margin:12px 0 7px;color:var(--ink)">“The short steps made it easier to bring this skill into a real work task.”</p><small>Example learner feedback · illustrative</small></article><article class="cap-card"><span class="mini-label">02 / Application</span><p style="margin:12px 0 7px;color:var(--ink)">“The practical exercise showed where our team needed to check the result.”</p><small>Example learner feedback · illustrative</small></article></div>`,'course-reviews');
  return result.replace('No invented ratings or testimonials are shown in this preview.','The sample feedback cards below demonstrate the review area; production should use verified learner reviews.').replace('Learner feedback will appear here only when verified reviews exist.','The review area below shows illustrative feedback for this design preview.');
};
const renderCore=render;
render=function(){
  const area=route().split('/')[0];
  const restricted={manager:['owner','setup','people','assessment','employee','path','assignment'],employee:['owner','setup','people','gap','manager','review','report'],owner:['manager','review','employee','path','assignment']};
  if(state.verified&&restricted[state.role]?.includes(area)){location.hash=`#/${rolePath(state.role)}`;return}
  renderCore();
};
